using std::unique_ptr;

// Compiler Implication: Comparisons require template checks
// on both T (Type) and D (Deleter) validity.

struct CustomDeleter { void operator()(int*) const noexcept {} };

using UPtr = unique_ptr<int, CustomDeleter>;

// 1. Comparing two different (or same) unique_ptrs
// Requires `T1* == T2*` comparison (address check)
bool ptr_compare(const UPtr& a, const UPtr& b) {
    return a.get() == b.get();
}

// 2. Comparison against nullptr_t
// Compiler optimization: Relies on dedicated overload or operator!
bool null_check(const UPtr& p) {
    return p == nullptr; // p.get() == nullptr
}

// 3. Comparison against Raw Pointer T*
// T must be implicitly comparable to the raw pointer type P*
bool raw_check(const UPtr& p, int* raw) {
    return p == raw;
}
